-- ========================================
-- 表: trade_orders
-- ========================================
CREATE TABLE trade_orders (
    PRIMARY KEY (id),
    id INTEGER NOT NULL DEFAULT nextval('trade_orders_id_seq'::regclass)
    trade_number VARCHAR(50) NOT NULL
    order_type VARCHAR(20) NOT NULL
    symbol VARCHAR(50) NOT NULL
    name VARCHAR(100) NULL
    price NUMERIC NOT NULL
    quantity INTEGER NOT NULL
    stop_loss_price NUMERIC NULL
    take_profit_price NUMERIC NULL
    psychological_score NUMERIC NULL
    strategy_score NUMERIC NULL
    risk_score NUMERIC NULL
    overall_score NUMERIC NULL
    order_date DATE NOT NULL
    order_time TIMESTAMPTZ NULL
    status VARCHAR(20) NOT NULL DEFAULT 'pending'::character varying
    is_virtual BOOLEAN NOT NULL DEFAULT false
    notes TEXT NULL
    deleted BOOLEAN NOT NULL DEFAULT false
    deleted_at TIMESTAMPTZ NULL
    created_at TIMESTAMPTZ NULL DEFAULT CURRENT_TIMESTAMP
    updated_at TIMESTAMPTZ NULL DEFAULT CURRENT_TIMESTAMP
    buy_order_id INTEGER NULL
);

CREATE INDEX idx_trade_orders_symbol idx_trade_orders_symbol ON public.trade_orders USING btree (symbol)

CREATE INDEX idx_trade_orders_status idx_trade_orders_status ON public.trade_orders USING btree (status)

CREATE INDEX idx_trade_orders_date idx_trade_orders_date ON public.trade_orders USING btree (order_date DESC)

CREATE INDEX idx_trade_orders_deleted idx_trade_orders_deleted ON public.trade_orders USING btree (deleted)

