-- ========================================
-- 表: trade_orders_backup
-- ========================================
CREATE TABLE trade_orders_backup (
    id INTEGER NULL
    trade_number VARCHAR(50) NULL
    order_type VARCHAR(10) NULL
    symbol VARCHAR(50) NULL
    name VARCHAR(200) NULL
    price NUMERIC NULL
    quantity INTEGER NULL
    stop_loss_price NUMERIC NULL
    take_profit_price NUMERIC NULL
    psychological_score NUMERIC NULL
    strategy_score NUMERIC NULL
    risk_score NUMERIC NULL
    overall_score NUMERIC NULL
    order_date DATE NULL
    order_time VARCHAR(8) NULL
    status VARCHAR(20) NULL
    is_virtual BOOLEAN NULL
    notes TEXT NULL
    deleted BOOLEAN NULL
    deleted_at TIMESTAMPTZ NULL
    created_at TIMESTAMPTZ NULL
    updated_at TIMESTAMPTZ NULL
);

-- ========================================
-- 表: trade_records
-- ========================================
CREATE TABLE trade_records (
    PRIMARY KEY (id),
    id INTEGER NOT NULL DEFAULT nextval('trade_records_id_seq'::regclass)
    deleted BOOLEAN NOT NULL DEFAULT false
    deleted_at TIMESTAMPTZ NULL
    created_at TIMESTAMPTZ NULL DEFAULT CURRENT_TIMESTAMP
    updated_at TIMESTAMPTZ NULL DEFAULT CURRENT_TIMESTAMP
    trade_number VARCHAR(20) NOT NULL
    trade_type VARCHAR(10) NULL
    symbol VARCHAR(50) NOT NULL
    name VARCHAR(200) NOT NULL
    buy_order_id VARCHAR(50) NULL
    sell_order_id VARCHAR(50) NULL
    buy_price NUMERIC NULL
    buy_quantity NUMERIC NULL
    buy_time TIMESTAMPTZ NULL
    buy_order_price NUMERIC NULL
    buy_order_time TIMESTAMPTZ NULL
    buy_psychological_score NUMERIC NULL
    buy_strategy_score NUMERIC NULL
    buy_strategy_id INTEGER NULL
    sell_price NUMERIC NULL
    sell_quantity NUMERIC NULL
    sell_time TIMESTAMPTZ NULL
    sell_order_price NUMERIC NULL
    sell_order_time TIMESTAMPTZ NULL
    sell_psychological_score NUMERIC NULL
    sell_strategy_score NUMERIC NULL
    sell_strategy_id INTEGER NULL
    buy_amount NUMERIC NULL
    sell_amount NUMERIC NULL
    profit NUMERIC NULL
    profit_percent NUMERIC NULL
    hold_duration INTEGER NULL
    buy_grade VARCHAR(10) NULL
    sell_grade VARCHAR(10) NULL
    overall_score NUMERIC NULL
    buy_channel JSON NULL
    sell_channel JSON NULL
    trade_summary TEXT NULL
    trade_commission NUMERIC NULL
    sell_trade_commission NUMERIC NULL
    other_fees NUMERIC NULL
    sell_other_fees NUMERIC NULL
    fees NUMERIC NULL
    slippage NUMERIC NULL
    net_profit NUMERIC NULL
    net_profit_percent NUMERIC NULL
    slippage_net_profit_ratio NUMERIC NULL
);

CREATE INDEX idx_trade_records_id idx_trade_records_id ON public.trade_records USING btree (id)

CREATE INDEX idx_trade_records_trade_number idx_trade_records_trade_number ON public.trade_records USING btree (trade_number)

CREATE INDEX idx_trade_records_symbol idx_trade_records_symbol ON public.trade_records USING btree (symbol)

CREATE INDEX idx_trade_records_trade_type idx_trade_records_trade_type ON public.trade_records USING btree (trade_type)

CREATE INDEX idx_trade_records_buy_time idx_trade_records_buy_time ON public.trade_records USING btree (buy_time DESC)

CREATE INDEX idx_trade_records_sell_time idx_trade_records_sell_time ON public.trade_records USING btree (sell_time DESC)

CREATE INDEX idx_trade_records_deleted idx_trade_records_deleted ON public.trade_records USING btree (deleted)

CREATE INDEX idx_trade_records_created_at idx_trade_records_created_at ON public.trade_records USING btree (created_at DESC)

CREATE INDEX idx_trade_records_buy_grade idx_trade_records_buy_grade ON public.trade_records USING btree (buy_grade)

CREATE INDEX idx_trade_records_sell_grade idx_trade_records_sell_grade ON public.trade_records USING btree (sell_grade)

