-- ========================================
-- 表: transactions
-- ========================================
CREATE TABLE transactions (
    PRIMARY KEY (id),
    id INTEGER NOT NULL DEFAULT nextval('transactions_id_seq'::regclass)
    order_id INTEGER NULL
    transaction_type VARCHAR(10) NULL
    symbol VARCHAR(50) NULL
    price NUMERIC NULL
    quantity NUMERIC NULL
    total_price NUMERIC NULL
    transaction_date DATE NULL
    transaction_time VARCHAR(8) NULL
    fee NUMERIC NULL DEFAULT 0
    profit NUMERIC NULL
    deleted BOOLEAN NOT NULL DEFAULT false
    deleted_at TIMESTAMPTZ NULL
    created_at TIMESTAMPTZ NULL DEFAULT CURRENT_TIMESTAMP
    updated_at TIMESTAMPTZ NULL DEFAULT CURRENT_TIMESTAMP
    name TEXT NULL
    description TEXT NULL
    amount TEXT NULL
    balance TEXT NULL
    account_type VARCHAR(20) NOT NULL DEFAULT 'realtime'::character varying
    trade_number VARCHAR(50) NULL
);

CREATE INDEX transactions_order_id_idx transactions_order_id_idx ON public.transactions USING btree (order_id)

CREATE INDEX transactions_date_idx transactions_date_idx ON public.transactions USING btree (transaction_date DESC)

CREATE INDEX transactions_symbol_idx transactions_symbol_idx ON public.transactions USING btree (symbol)

CREATE INDEX transactions_type_idx transactions_type_idx ON public.transactions USING btree (transaction_type)

CREATE INDEX transactions_created_at_idx transactions_created_at_idx ON public.transactions USING btree (created_at DESC)

